#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

// Read the assets.json file generated by Vike
const assetsPath = path.resolve(__dirname, '../dist/assets.json');
const manifestPath = path.resolve(__dirname, '../dist/client/manifest.json');

try {
  // Check if assets.json exists
  if (!fs.existsSync(assetsPath)) {
    console.error('assets.json not found at:', assetsPath);
    process.exit(1);
  }

  // Read assets.json
  const assets = JSON.parse(fs.readFileSync(assetsPath, 'utf-8'));

  // Create manifest.json with the same structure
  // The deployment script checks for page routes with pattern /(^pages\/).+(\.tsx|\.jsx)/
  const manifest = {};

  // Copy all entries that match page routes
  Object.keys(assets).forEach(key => {
    // Include all page entries
    if (key.startsWith('pages/') && (key.endsWith('.tsx') || key.endsWith('.jsx'))) {
      manifest[key] = assets[key];
    }
  });

  // Ensure client directory exists
  const clientDir = path.dirname(manifestPath);
  if (!fs.existsSync(clientDir)) {
    fs.mkdirSync(clientDir, { recursive: true });
  }

  // Write manifest.json
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2));
  console.log('Generated manifest.json with', Object.keys(manifest).length, 'page routes');
} catch (error) {
  console.error('Error generating manifest.json:', error);
  process.exit(1);
}
